import math

def is_square(k):
    if k < 1:
        return False
    sqrt_k = int(math.isqrt(k))
    return sqrt_k * sqrt_k == k

def is_cool(n):
    if n == 1:
        # Sum is 1, which is 1^2. So n=1 is NOT cool.
        return False

    # State: (current_sum, used_mask)
    # used_mask is a bitmask where the j-th bit is set if j+1 is used.

    def backtrack(current_sum, used_mask, count):
        if count == n:
            # If we successfully constructed a permutation of length n, 
            # the sum is T_n. The problem implies S_n must also not be a perfect square.
            # However, the loop condition 'for any i' usually includes i=n.
            # The final sum is T_n.
            if is_square(current_sum):
                return False
            return True

        # Try appending every unused number j (from 1 to n)
        for j in range(1, n + 1):
            if not (used_mask & (1 << (j - 1))):
                next_sum = current_sum + j

                # Check the constraint: the new prefix sum must not be a square
                if not is_square(next_sum):
                    new_mask = used_mask | (1 << (j - 1))

                    if backtrack(next_sum, new_mask, count + 1):
                        return True

        return False

    # Start the search
    return backtrack(0, 0, 0)

